package org.humanjourney.core.mapfeature.client;
public enum FeatureMode{HOVER,ALL,OFF;public String id(){return name().toLowerCase(java.util.Locale.ROOT);}public String label(){return "HJ Features: "+name().charAt(0)+name().substring(1).toLowerCase(java.util.Locale.ROOT);}public FeatureMode next(){return values()[(ordinal()+1)%values().length];}public static boolean valid(Object o){return o instanceof String s&&java.util.Arrays.stream(values()).anyMatch(m->m.id().equals(s));}public static FeatureMode parse(String s){return java.util.Arrays.stream(values()).filter(m->m.id().equals(s)).findFirst().orElse(HOVER);}}
